ll binpow(int a, int n){
    if(n == 0) return 1;
    ll X = binpow(a, n / 2);   // a^(n/2)
    if(n % 2 == 1) return X * X * a;
    else return X * X;
}

ll binpow(ll a, ll n){
    ll res = 1;
    while(n != 0){
        if(n & 1) res *= a;   // bit cuối là 1
        n >>= 1;              // dịch phải 1 bit
        a *= a;
    }
    return res;
}

ll binpow(ll a, ll n, ll c){
    ll res = 1;
    a %= c;
    while(n != 0){
        if(n % 2 == 1){ res *= (a % c); res %= c; }
        n /= 2;
        a *= (a % c); a %= c;
    }
    return res;
}
